import{_ as s,o as e,c as l,a0 as n}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"linux软件管理","description":"","frontmatter":{},"headers":[],"relativePath":"linux/software.md","filePath":"linux/software.md","lastUpdated":1791039142000}'),i={name:"linux/software.md"};function o(t,a,r,p,c,d){return e(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="linux软件管理" tabindex="-1">linux软件管理 <a class="header-anchor" href="#linux软件管理" aria-label="Permalink to &quot;linux软件管理&quot;">​</a></h1><h2 id="软件包分类" tabindex="-1">软件包分类 <a class="header-anchor" href="#软件包分类" aria-label="Permalink to &quot;软件包分类&quot;">​</a></h2><ul><li>源码包（未编译的源码）</li><li>二进制包（RPM包、系统默认包，即编译过的）</li></ul><h3 id="源码包" tabindex="-1">源码包 <a class="header-anchor" href="#源码包" aria-label="Permalink to &quot;源码包&quot;">​</a></h3><h4 id="源码包优点" tabindex="-1">源码包优点 <a class="header-anchor" href="#源码包优点" aria-label="Permalink to &quot;源码包优点&quot;">​</a></h4><ul><li>开源，可以修改源代码</li><li>可以自由选择所需的功能</li><li>软件是编译安装，所以更加适合自己的系统，更加稳定效率也更高</li><li>卸载方便（只要把安装目录删除）</li></ul><h4 id="源码包的缺点" tabindex="-1">源码包的缺点 <a class="header-anchor" href="#源码包的缺点" aria-label="Permalink to &quot;源码包的缺点&quot;">​</a></h4><ul><li>安装过程步骤较多，尤其安装较大的软件集合时，容易出现拼写错误</li><li>编译过程时间较长，安装比二进制安装时间长</li><li>因为是编译安装，安装过程中一旦报错新手很难解决</li></ul><h3 id="rpm包-二进制包" tabindex="-1">RPM包（二进制包） <a class="header-anchor" href="#rpm包-二进制包" aria-label="Permalink to &quot;RPM包（二进制包）&quot;">​</a></h3><p>系统光盘里有大部分要用到的rpm包，挂载后就可以使用rpm安装</p><h4 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h4><ul><li>包管理系统简单，只通过几个命令就可以实现包的安装、升级查询和卸载</li><li>安装速度比源码包安装快的多</li></ul><h4 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h4><ul><li>经过编译，不再可以看到源代码</li><li>功能选择不如源码包灵活</li><li>依赖性（有可能会依赖其他的软件包，需要手动去安装）</li></ul><h4 id="命名规则" tabindex="-1">命名规则 <a class="header-anchor" href="#命名规则" aria-label="Permalink to &quot;命名规则&quot;">​</a></h4><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>httpd-2.2.15-15.el6.centos.1.i686.rpm</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>httpd</code> 软件包名</li><li><code>2.2.15</code> 软件版本</li><li><code>15</code> 软件发布的次数</li><li><code>el6.centos</code> 适合linux平台</li><li><code>i686</code> 适合的硬件平台</li><li><code>rpm</code> rpm包扩展名</li></ul><h3 id="脚本安装包" tabindex="-1">脚本安装包 <a class="header-anchor" href="#脚本安装包" aria-label="Permalink to &quot;脚本安装包&quot;">​</a></h3><p>所谓的脚本安装包，就是把复杂的软件包安装过程写成了程序脚本，可以执行程序实现一键安装。但实际安装的还是源码包或二进制包。 安装简单快捷，但是完全丧失了自定义性。</p><h2 id="rpm命令管理" tabindex="-1">RPM命令管理 <a class="header-anchor" href="#rpm命令管理" aria-label="Permalink to &quot;RPM命令管理&quot;">​</a></h2><p>系统光盘里有大部分要用到的rpm包，挂载后就可以使用rpm安装</p><h3 id="安装命令" tabindex="-1">安装命令 <a class="header-anchor" href="#安装命令" aria-label="Permalink to &quot;安装命令&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">ivh 包全名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h4><ul><li><code>-i(install)</code> 安装</li><li><code>-v(verbose)</code> 显示详细信息</li><li><code>-h(hash)</code> 显示进度</li><li><code>--nodeps</code> 不检测依赖性</li></ul><h3 id="升级与卸载" tabindex="-1">升级与卸载 <a class="header-anchor" href="#升级与卸载" aria-label="Permalink to &quot;升级与卸载&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">Uvh 包全名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>-U(upgrade)</code> 升级</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果原软件包不存在，则该命令相当于安装命令，如果存在则为升级</p></div><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">e 包名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>-e(erase)</code> 卸载</li><li><code>--nodeps</code> 不检测依赖性</li></ul><h3 id="rpm包查询" tabindex="-1">RPM包查询 <a class="header-anchor" href="#rpm包查询" aria-label="Permalink to &quot;RPM包查询&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">q 包名              </span><span style="color:#6A737D;">//查询包是否安装</span></span>
<span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">qa                  </span><span style="color:#6A737D;">//查询所有已安装的RPM包</span></span>
<span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">qi 包名             </span><span style="color:#6A737D;">//查询软件包的详细信息</span></span>
<span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">ql 包名             </span><span style="color:#6A737D;">//查询包中文件安装位置</span></span>
<span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">qf 系统文件名       </span><span style="color:#6A737D;">//查询系统文件属于哪个包</span></span>
<span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">qR 包名             </span><span style="color:#6A737D;">//查询软件包的依赖性</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><code>-p</code> 查询未安装包的信息</li></ul><h4 id="rpm包默认安装位置" tabindex="-1">RPM包默认安装位置 <a class="header-anchor" href="#rpm包默认安装位置" aria-label="Permalink to &quot;RPM包默认安装位置&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;">/etc/</td><td style="text-align:left;">配置文件安装目录</td></tr><tr><td style="text-align:left;">/user/bin/</td><td style="text-align:left;">可执行的命令安装目录</td></tr><tr><td style="text-align:left;">/user/lib/</td><td style="text-align:left;">程序所使用的函数库保存位置</td></tr><tr><td style="text-align:left;">/user/share/doc/</td><td style="text-align:left;">基本的软件使用手册保存位置</td></tr><tr><td style="text-align:left;">/user/share/man/</td><td style="text-align:left;">帮助文件保存位置</td></tr></tbody></table><h3 id="rpm包校验" tabindex="-1">RPM包校验 <a class="header-anchor" href="#rpm包校验" aria-label="Permalink to &quot;RPM包校验&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">rpm </span><span style="color:#D73A49;">-</span><span style="color:#005CC5;">V</span><span style="color:#24292E;"> 已安装的包名       </span><span style="color:#6A737D;">//校验指定RPM包中的文件（verify）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="验证内容中的信息" tabindex="-1">验证内容中的信息 <a class="header-anchor" href="#验证内容中的信息" aria-label="Permalink to &quot;验证内容中的信息&quot;">​</a></h4><ul><li><code>S</code> 文件大小是否改变</li><li><code>M</code> 文件的类型或文件的权限（rwx）是否改变</li><li><code>5</code> 文件MD5校验和是否改变（可以看成文件内容是否改变）</li><li><code>D</code> 设备的主从代码是否改变</li><li><code>L</code> 文件路径是否改变</li><li><code>U</code> 文件的属主（所有者）是否改变</li><li><code>G</code> 文件的属组是否改变</li><li><code>T</code> 文件的修改时间是否改变</li></ul><h4 id="文件类型" tabindex="-1">文件类型 <a class="header-anchor" href="#文件类型" aria-label="Permalink to &quot;文件类型&quot;">​</a></h4><ul><li><code>c</code> 配置文件（config file）</li><li><code>d</code> 普通文件（documentation）</li><li><code>g</code> ghost file，该文件不应该被这个RPM包包含</li><li><code>L</code> 授权文件（license file）</li><li><code>r</code> 描述文件（read me）</li></ul><h2 id="yum在线安装" tabindex="-1">yum在线安装 <a class="header-anchor" href="#yum在线安装" aria-label="Permalink to &quot;yum在线安装&quot;">​</a></h2><p>将所有软件包放到官方服务器上，当进行yum在线安装时，可以自动解决依赖心问题</p><h3 id="yum源文件" tabindex="-1">yum源文件 <a class="header-anchor" href="#yum源文件" aria-label="Permalink to &quot;yum源文件&quot;">​</a></h3><p>即yum配置文件</p><h4 id="文件位置" tabindex="-1">文件位置 <a class="header-anchor" href="#文件位置" aria-label="Permalink to &quot;文件位置&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">vi </span><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">yum.repos.d</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">CentOS</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">Base.repo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>[base]</code> 容器名称，一定要放在[]中</li><li><code>name</code> 容器说明，可以自己随便写</li><li><code>mirrorlist</code> 镜像站点，这个可以注释掉</li><li><code>baseurl</code> yum源服务器的地址。默认是CentOS官方的yum源服务器，是可以使用的，可以改成其他的yum源地址</li><li><code>enabled</code> 此容器是否生效，如果不写或写成enable=1都是生效，写成enable=0就是不生效</li><li><code>gpgcheck</code> 如果是1是指RPM的数字证书生效，如果是0则不生效</li><li><code>gpgkey</code> 数字证书的公钥文件保存位置。不用修改</li></ul><h3 id="光盘搭建yum源" tabindex="-1">光盘搭建yum源 <a class="header-anchor" href="#光盘搭建yum源" aria-label="Permalink to &quot;光盘搭建yum源&quot;">​</a></h3><h4 id="挂载光盘" tabindex="-1">挂载光盘 <a class="header-anchor" href="#挂载光盘" aria-label="Permalink to &quot;挂载光盘&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">mkdir </span><span style="color:#D73A49;">/</span><span style="color:#24292E;">mnt</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">cdrom                </span><span style="color:#6A737D;">//建立挂载点</span></span>
<span class="line"><span style="color:#24292E;">mount </span><span style="color:#D73A49;">/</span><span style="color:#24292E;">dev</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">cdrom </span><span style="color:#D73A49;">/</span><span style="color:#24292E;">mnt</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">cdrom</span><span style="color:#D73A49;">/</span><span style="color:#6A737D;">    //挂载光盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="修改yum源" tabindex="-1">修改yum源 <a class="header-anchor" href="#修改yum源" aria-label="Permalink to &quot;修改yum源&quot;">​</a></h4><p>使网络yum源失效，即删除 CentOS-Base.repo 文件。然后修改光盘yum源，即CentOS-Media.repo</p><h3 id="yum命令" tabindex="-1">yum命令 <a class="header-anchor" href="#yum命令" aria-label="Permalink to &quot;yum命令&quot;">​</a></h3><h4 id="查询" tabindex="-1">查询 <a class="header-anchor" href="#查询" aria-label="Permalink to &quot;查询&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">yum list                        </span><span style="color:#6A737D;">// 查询所有可用软件包列表</span></span>
<span class="line"><span style="color:#24292E;">yum search [关键字]             </span><span style="color:#6A737D;">// 搜索服务器上所有和关键字相关的包</span></span>
<span class="line"><span style="color:#24292E;">yum list installed              </span><span style="color:#6A737D;">// 列出所有已安装的软件包</span></span>
<span class="line"><span style="color:#24292E;">yum list updates                </span><span style="color:#6A737D;">// 列出所有可更新的软件包</span></span>
<span class="line"><span style="color:#24292E;">yum info installed              </span><span style="color:#6A737D;">// 列出所有已安装的软件包信息</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">yum </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">y install 包名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项</p><ul><li><code>install</code> //安装</li><li><code>-y</code> //自动回答yes</li></ul><h4 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">yum </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">y update 包名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">yum </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">y remove</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="软件组管理" tabindex="-1">软件组管理 <a class="header-anchor" href="#软件组管理" aria-label="Permalink to &quot;软件组管理&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">yum grouplist               </span><span style="color:#6A737D;">//列出所有可用的软件组列表</span></span>
<span class="line"><span style="color:#24292E;">yum groupinstall 软件组名   </span><span style="color:#6A737D;">//安装指定软件组，组名可以有grouplist查询出来</span></span>
<span class="line"><span style="color:#24292E;">yum groupremove 软件组名    </span><span style="color:#6A737D;">//卸载指定软件组</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="脚本安装" tabindex="-1">脚本安装 <a class="header-anchor" href="#脚本安装" aria-label="Permalink to &quot;脚本安装&quot;">​</a></h2><p>脚本安装实际上还是安装的源码包与RPM包，只是把安装过程写成了脚本，便于初学者安装。</p><p>优点：简单、快速、方便</p><p>缺点：</p><ul><li>不能定义安装软件的版本</li><li>不能定义所需要的软件功能</li><li>源码包的优势丧失</li></ul>`,72)])])}const b=s(i,[["render",o]]);export{h as __pageData,b as default};
